require_once __DIR__ . '/includes/auth.php'; require_login();$userId=(int)$_SESSION['user_id'];archive_completed_years($pdo,$userId);$statement=$pdo->prepare('SELECT * FROM yearly_archive WHERE user_id=:user_id ORDER BY year DESC');$statement->execute(['user_id'=>$userId]);$archives=$statement->fetchAll();$pageTitle='Yearly archive';require __DIR__.'/includes/header.php';
?><div class="page-title"><div><span class="eyebrow">A RECORD OF PROGRESS</span><h1>Yearly Savings Archive</h1></div></div><section class="panel"><p class="muted">Completed calendar years are saved automatically and refreshed without duplicates.</p><div class="table-wrap"><table class="table stats-table"><thead><tr><th>Year</th><th>Total income</th><th>Total expense</th><th>Saved balance</th></tr></thead><tbody><?php if(!$archives): ?><tr><td colspan="4" class="empty-state">No completed yearly cycle yet.</td></tr><?php else: foreach($archives as $archive): ?><tr><td><?=e((string)$archive['year'])?></td><td class="text-success"><?=money($archive['total_income'])?></td><td class="text-danger"><?=money($archive['total_expense'])?></td><td><?=money($archive['total_balance'])?></td></tr><?php endforeach; endif; ?></tbody></table></div></section><?php require __DIR__.'/includes/footer.php'; ?>
